def convertir(serie, censure="moitie"):
    """Convertit une colonne de la table Ciqual en nombres.

    censure : traitement des valeurs '< x'
        'zero'   -> 0
        'moitie' -> x/2 (convention courante)
        'seuil'  -> x
        'nan'    -> valeur manquante
    """
    def un(v):
        s = str(v).strip()
        if s in ("-", "", "nan"):
            return np.nan
        if s == "traces":
            return 0.0
        if s.startswith("<"):
            seuil = float(s[1:].replace(",", "."))
            return {"zero": 0.0, "moitie": seuil / 2, "seuil": seuil, "nan": np.nan}[censure]
        return float(s.replace(",", "."))
    return serie.map(un)

